// Extract the real five Lua bodies without importing billing/application code.
// Execute only the import-free TypeScript version/key helpers in a VM.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import vm from 'node:vm';
const root = new URL('../../../', import.meta.url);
const require = createRequire(new URL('dimabot/package.json', root));
const ts = require('typescript');
const files = ['src/utils/plan_cache_fence.ts', 'src/domain_events/polar_billing_events.ts'];
const texts = files.map(path => readFileSync(new URL(`dimabot/${path}`, root), 'utf8'));
const names = ['WRITE_PLAN_ACCOUNT_SCRIPT', 'CHECK_PLAN_ACCOUNTS_SCRIPT', 'ACCEPT_PLAN_CREDITS_SCRIPT', 'INVALIDATE_PLAN_SCRIPT', 'SYNC_CREDITS_SCRIPT'];
const scripts = new Map();
for (let index = 0; index < files.length; index++) {
  const parsed = ts.createSourceFile(files[index], texts[index], ts.ScriptTarget.Latest, true);
  function visit(node) {
    if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name) && names.includes(node.name.text)) {
      assert.ok(ts.isNoSubstitutionTemplateLiteral(node.initializer));
      scripts.set(node.name.text, node.initializer.text);
    }
    ts.forEachChild(node, visit);
  }
  visit(parsed);
}
assert.equal(scripts.size, 5);
const module = { exports: {} };
vm.runInNewContext(ts.transpileModule(texts[0], { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText, { module, exports: module.exports });
const helpers = module.exports;
const cases = [];
for (const at of [undefined, -8640000000000000, -1234567890123, -1, 0, 1, 12345, 9999999999999, 10000000000000, 1793100600000, 8640000000000000]) {
  for (const key of [undefined, '', 'event', '0', 'event:part', 'é😀']) {
    cases.push({ at, key, expected: helpers.planCacheVersion(at === undefined ? undefined : new Date(at), key) });
  }
}
const raw = value => `r###"${value}"###`;
let out = '// Generated by plan_cache_fence_reference.mjs; do not edit.\n';
for (let i = 0; i < files.length; i++) out += `// ${files[i]} SHA256 ${createHash('sha256').update(texts[i]).digest('hex')}\n`;
out += '// Invalid/out-of-range JS Dates with a nonempty key are rejected by Rust.\n';
out += '#[rustfmt::skip]\npub const SOURCE_SCRIPTS: &[(&str, &str)] = &[\n';
for (const name of names) out += `    (${raw(name)}, ${raw(scripts.get(name))}),\n`;
out += '];\n';
out += 'pub type VersionCase = (Option<i64>, Option<&\'static str>, &\'static str);\n';
out += '#[rustfmt::skip]\npub const VERSION_CASES: &[VersionCase] = &[\n';
for (const { at, key, expected } of cases) out += `    (${at === undefined ? 'None' : `Some(${at})`}, ${key === undefined ? 'None' : `Some(${raw(key)})`}, ${raw(expected)}),\n`;
out += '];\n';
out += `pub const SOURCE_VERSION_FIELD: &str = ${raw(helpers.PLAN_CACHE_VERSION_FIELD)};\n`;
out += '#[rustfmt::skip]\npub const KEY_CASES: &[(&str, &str)] = &[\n';
for (const id of ['', '123', 'owner-123', 'é😀', 'a:b']) out += `    (${raw(id)}, ${raw(helpers.planCacheFenceKey(id))}),\n`;
out += '];\n';
const destination = new URL('plan_cache_fence_source.rs', import.meta.url);
if (process.argv.includes('--check')) assert.equal(readFileSync(destination, 'utf8'), out, 'regenerate plan-cache source fixture');
else writeFileSync(destination, out);
console.log(`Plan-cache source oracle: 5 scripts, ${cases.length} version cases, 5 key cases; ${process.argv.includes('--check') ? 'fixture matches' : 'fixture written'}; no application imports or network.`);
